insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As funções de polícia marítima, aeroportuária e de fronteira serão realizadas pela Polícia Federal nos pontos de entrada e de saída do território nacional. É dispensável a fiscalização de passageiro, tripulante e estafe de navio em passagem inocente, exceto quando houver necessidade de descida de pessoa a terra ou de subida a bordo.', '["Polícia Federal faz a polícia marítima, aeroportuária e de fronteira.","Passagem inocente dispensa fiscalização, salvo descida ou subida de pessoas."]'::jsonb, '["Quem fiscaliza a entrada e saída é a POLÍCIA FEDERAL."]'::jsonb, 'A PF confere os documentos no aeroporto.', '["Assertiva que atribui essa fiscalização à Receita Federal erra: é da Polícia Federal."]'::jsonb, '[{"termo":"Passagem inocente","significado":"Passagem de navio pelo mar territorial sem escala e sem prejuízo ao Estado."}]'::jsonb, '["Constituição (Polícia Federal)"]'::jsonb, 'under_review', 'claude'
