insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderá ser autorizada a admissão excepcional no País de pessoa que esteja de posse de documento de viagem válido e que não possua visto; seja titular de visto emitido com erro ou omissão; tenha perdido a condição de residente por ausência prolongada e detenha condições para nova autorização; ou seja criança ou adolescente desacompanhado de responsável legal e sem autorização para viajar sozinho, caso em que haverá imediato encaminhamento ao Conselho Tutelar ou a instituição indicada. Regulamento poderá dispor sobre outras hipóteses.', '["Admissão excepcional com documento de viagem válido.","Sem visto, visto com erro, perda de residência por ausência.","Criança ou adolescente desacompanhado: Conselho Tutelar."]'::jsonb, '["Criança desacompanhada vai ao CONSELHO TUTELAR."]'::jsonb, 'O adolescente que chega sozinho, sem autorização, é encaminhado ao Conselho Tutelar.', '["Assertiva que manda repatriar de imediato a criança desacompanhada erra: ela é encaminhada ao Conselho Tutelar."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
