on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A expulsão consiste em medida administrativa de retirada compulsória de migrante ou visitante do território nacional, conjugada com o impedimento de reingresso por prazo determinado. Pode dar causa à expulsão a condenação com trânsito em julgado por crime de genocídio, contra a humanidade, de guerra ou de agressão, ou por crime comum doloso passível de pena privativa de liberdade, consideradas a gravidade e as possibilidades de ressocialização. A autoridade competente resolve sobre a expulsão, a duração do impedimento e a suspensão ou revogação dos efeitos. O processamento da expulsão não prejudica progressão de regime, cumprimento da pena, suspensão condicional do processo, comutação, pena alternativa, indulto ou anistia concedidos em igualdade com o brasileiro.', '["Retirada compulsória com impedimento de reingresso por prazo determinado.","Causas: condenação transitada em julgado por crimes graves.","Não prejudica benefícios penais em igualdade com o nacional."]'::jsonb, '["Expulsão exige condenação com TRÂNSITO EM JULGADO."]'::jsonb, 'O estrangeiro condenado definitivamente por crime doloso grave pode ser expulso.', '["Assertiva que permite expulsão por mera acusação, sem condenação, erra."]'::jsonb, '[]'::jsonb, '["Art. 55"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-54'
