insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As políticas públicas para os emigrantes observarão os princípios de proteção e assistência consular; promoção de condições de vida digna, com registro consular e serviços consulares; estudos e pesquisas sobre os emigrantes; atuação diplomática em defesa dos direitos do emigrante; ação governamental integrada; e esforço permanente de desburocratização e modernização do atendimento.', '["Assistência consular.","Vida digna e serviços consulares.","Estudos sobre emigrantes.","Atuação diplomática.","Ação integrada e desburocratização."]'::jsonb, '["Protege o brasileiro no exterior (EMIGRANTE)."]'::jsonb, 'O consulado presta assistência ao brasileiro que vive no exterior.', '["Assertiva que trata das políticas para imigrantes em vez de emigrantes erra."]'::jsonb, '[]'::jsonb, '["Art. 78"]'::jsonb, 'under_review', 'claude'
