select u.id, u.content_sha256, 'Todo emigrante que decida retornar ao Brasil com ânimo de residência poderá introduzir no País, com isenção de direitos de importação e de taxas aduaneiras, os bens novos ou usados que um viajante, em compatibilidade com as circunstâncias de sua viagem, puder destinar para seu uso ou consumo pessoal e profissional, desde que, por sua quantidade, natureza ou variedade, não permitam presumir importação com fins comerciais ou industriais.', '["Isenção de importação para bens de uso pessoal e profissional.","Vale ao emigrante que retorna com ânimo de residência."]'::jsonb, '["Sem fins comerciais ou industriais."]'::jsonb, 'O brasileiro que volta ao País traz seus pertences pessoais com isenção.', '["Assertiva que permite a isenção para bens destinados ao comércio erra."]'::jsonb, '[]'::jsonb, '["Art. 77"]'::jsonb, 'under_review', 'claude'
