insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O pedido de extradição originado de Estado estrangeiro será recebido pelo órgão competente do Poder Executivo e, após exame dos pressupostos formais de admissibilidade, encaminhado à autoridade judiciária competente. Não preenchidos os pressupostos, o pedido será arquivado mediante decisão fundamentada, sem prejuízo de renovação, devidamente instruído, uma vez superado o óbice.', '["Executivo recebe e examina os pressupostos formais.","Encaminhamento ao Judiciário.","Arquivamento fundamentado, com possibilidade de renovar."]'::jsonb, '["Extradição PASSIVA: outro país pede ao Brasil."]'::jsonb, 'O Executivo examina o pedido do país estrangeiro antes de enviá-lo ao STF.', '["Assertiva que torna definitivo o arquivamento do pedido erra: pode ser renovado."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
