select u.id, u.content_sha256, 'Nenhuma extradição será concedida sem prévio pronunciamento do Supremo Tribunal Federal sobre sua legalidade e procedência, não cabendo recurso da decisão.', '["Prévio pronunciamento do STF.","Sem recurso."]'::jsonb, '["O STF controla a LEGALIDADE e a PROCEDÊNCIA."]'::jsonb, 'Só com a decisão do STF a extradição é concedida.', '["Assertiva que permite a extradição sem decisão do STF erra."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
