insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao receber o pedido, o relator designará dia e hora para o interrogatório do extraditando e, conforme o caso, nomear-lhe-á curador ou advogado, se não o tiver. A defesa, no prazo de 10 dias contado do interrogatório, versará sobre a identidade da pessoa reclamada, defeito de forma de documento ou ilegalidade da extradição. Não estando o processo instruído, o Tribunal poderá converter o julgamento em diligência, e o Ministério Público Federal terá prazo improrrogável de 60 dias para supri-la, contado da notificação à missão diplomática do Estado requerente.', '["Interrogatório do extraditando.","Defesa em 10 dias: identidade, defeito de forma e ilegalidade.","Diligência com prazo improrrogável de 60 dias."]'::jsonb, '["A defesa só discute IDENTIDADE, FORMA e ILEGALIDADE (não o mérito)."]'::jsonb, 'O extraditando apresenta defesa em 10 dias sobre sua identidade e a forma dos documentos.', '["Assertiva que permite discutir o mérito da acusação na defesa da extradição erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-91'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Julgada procedente a extradição e autorizada a entrega pelo órgão competente do Poder Executivo, o ato será comunicado por via diplomática ao Estado requerente, que, no prazo de 60 dias da comunicação, deverá retirar o extraditando do território nacional.', '["Prazo de 60 dias para o Estado requerente retirar o extraditando."]'::jsonb, '["Prazo de 60 dias."]'::jsonb, 'O país requerente tem 60 dias para buscar o extraditando.', '["Assertiva que fixa em 30 dias o prazo de retirada erra: são 60."]'::jsonb, '[]'::jsonb, '["Art. 93"]'::jsonb, 'under_review', 'claude'
