on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o Estado requerente não retirar o extraditando do território nacional no prazo previsto no art. 92, será ele posto em liberdade, sem prejuízo de outras medidas aplicáveis.', '["Soltura se o Estado requerente não retirar o extraditando no prazo."]'::jsonb, '["Consequência: liberdade."]'::jsonb, 'Passados os 60 dias sem retirada, o extraditando é solto.', '["Assertiva que mantém a prisão indefinidamente se o Estado não retira o extraditando erra."]'::jsonb, '[]'::jsonb, '["Art. 92"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-93'
