insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Negada a extradição em fase judicial, não se admitirá novo pedido baseado no mesmo fato.', '["Negada a extradição, não se admite novo pedido pelo mesmo fato."]'::jsonb, '["Coisa julgada na extradição."]'::jsonb, 'Se o STF nega a extradição, o mesmo fato não pode embasar novo pedido.', '["Assertiva que permite renovar o pedido após a negativa judicial erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-94'
