insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A entrega do extraditando, de acordo com as leis brasileiras e respeitado o direito de terceiro, será feita com os objetos e instrumentos do crime encontrados em seu poder. Os objetos e instrumentos poderão ser entregues independentemente da entrega do extraditando.', '["Entrega com os objetos e instrumentos do crime.","Possível entregá-los separadamente."]'::jsonb, '["Respeita direito de terceiro."]'::jsonb, 'A arma do crime é entregue junto com o extraditando.', '["Assertiva que impede a entrega dos objetos do crime sem o extraditando erra."]'::jsonb, '[]'::jsonb, '["Art. 96"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-97'
