on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A forma do pedido de transferência de execução da pena e seu processamento serão definidos em regulamento. Nos casos previstos nesta Seção, a execução penal será de competência da Justiça Federal.', '["Forma e processamento em regulamento.","Execução penal na Justiça Federal."]'::jsonb, '["Competência da JUSTIÇA FEDERAL para a execução."]'::jsonb, 'A pena transferida é executada pela Justiça Federal.', '["Assertiva que atribui a execução à Justiça Estadual erra: é da Justiça Federal."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-102'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A transferência de pessoa condenada poderá ser concedida quando o pedido se fundamentar em tratado ou houver promessa de reciprocidade. O condenado no território nacional poderá ser transferido para seu país de nacionalidade ou país em que tiver residência habitual ou vínculo pessoal, desde que expresse interesse, para cumprir a pena imposta pelo Brasil por sentença transitada em julgado. A transferência pode ser concedida com medida de impedimento de reingresso no território nacional.', '["Transferência com base em tratado ou reciprocidade.","Condenado no Brasil cumpre pena em seu país, se tiver interesse.","Pode haver impedimento de reingresso."]'::jsonb, '["Exige INTERESSE do condenado."]'::jsonb, 'O estrangeiro condenado no Brasil pede para cumprir a pena em seu país.', '["Assertiva que dispensa o interesse do condenado na transferência erra."]'::jsonb, '[]'::jsonb, '["Art. 104"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'migracao' and u.unit_key = 'art-103'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A transferência de pessoa condenada será possível quando o condenado no território de uma das partes for nacional ou tiver residência habitual ou vínculo pessoal no território da outra parte; a sentença tiver transitado em julgado; a duração da condenação a cumprir for de pelo menos 1 ano na data do pedido; o fato constituir infração penal perante a lei de ambos os Estados; houver manifestação de vontade do condenado ou de seu representante; e houver concordância de ambos os Estados.', '["Nacionalidade ou vínculo.","Trânsito em julgado.","Pelo menos 1 ano a cumprir.","Dupla incriminação.","Vontade do condenado e concordância dos dois Estados."]'::jsonb, '["Seis requisitos cumulativos."]'::jsonb, 'A transferência exige a vontade do condenado e a concordância dos dois países.', '["Assertiva que dispensa a concordância de um dos Estados erra."]'::jsonb, '[]'::jsonb, '["Art. 103"]'::jsonb, 'under_review', 'claude'
