insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regulamento disporá sobre o procedimento de apuração das infrações administrativas e seu processamento e sobre a fixação e a atualização das multas, em observância ao disposto na Lei.', '["Procedimento e multas por regulamento."]'::jsonb, '["Matéria regulamentar."]'::jsonb, 'O regulamento detalha como se apura a infração migratória.', '["Assertiva que fixa todos os procedimentos na própria Lei erra."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
