insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penalidades aplicadas serão objeto de pedido de reconsideração e de recurso, nos termos de regulamento. Serão respeitados o contraditório, a ampla defesa e a garantia de recurso, assim como a situação de hipossuficiência do migrante ou do visitante.', '["Reconsideração e recurso.","Contraditório, ampla defesa e consideração da hipossuficiência."]'::jsonb, '["Considera a hipossuficiência do migrante."]'::jsonb, 'O migrante pobre pode recorrer da multa, com garantias.', '["Assertiva que nega recurso contra as penalidades erra."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
