insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei não prejudica direitos e obrigações estabelecidos por tratados vigentes no Brasil e que sejam mais benéficos ao migrante e ao visitante, em particular os tratados firmados no âmbito do Mercosul.', '["Tratados mais benéficos prevalecem.","Em especial os do Mercosul."]'::jsonb, '["Prevalece o tratado MAIS BENÉFICO."]'::jsonb, 'O cidadão do Mercosul usa o acordo de residência mais favorável.', '["Assertiva que sobrepõe a Lei a tratados mais benéficos ao migrante erra."]'::jsonb, '[]'::jsonb, '["Art. 122"]'::jsonb, 'under_review', 'claude'
