insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As autoridades brasileiras serão tolerantes quanto ao uso do idioma do residente fronteiriço e do imigrante quando eles se dirigirem a órgãos ou repartições públicas para reclamar ou reivindicar os direitos decorrentes da Lei.', '["Tolerância quanto ao idioma do residente fronteiriço e do imigrante."]'::jsonb, '["Não se exige o português para reclamar direitos."]'::jsonb, 'O imigrante que fala outro idioma é atendido na repartição pública.', '["Assertiva que exige o português para qualquer reclamação do imigrante erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
